const PROMPT =
  "Find the top 20 reviews of the AirPods Pro on Amazon and tell me what people complain about most.";

const SceneTyping: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const chromeIn = springIn(frame, fps, 0, "LIQUID");
  // Typing reveal — character by character, realistic pace
  const typingStart = 8;
  const charsPerFrame = 0.65;
  const charsShown = Math.min(
    PROMPT.length,
    Math.max(0, Math.floor((frame - typingStart) * charsPerFrame))
  );
  const visibleText = PROMPT.slice(0, charsShown);
  const cursorBlink = Math.floor((frame / 12) % 2);
  const driftY = ambientDrift(frame, 2, 120, "typing-chrome");

  return (
    <AbsoluteFill style={{ fontFamily: BRAND.fonts.primary }}>
      <div style={{ position: "absolute", inset: 0, transform: `translateY(${driftY}px)` }}>
        <ClaudeChrome chromeIn={chromeIn}>
          {/* Input box, growing as text fills */}
          <div
            style={{
              position: "absolute",
              left: "8%",
              right: "8%",
              bottom: "8%",
              backgroundColor: "#161718",
              border: `1px solid ${charsShown > 0 ? COLORS.orange : COLORS.border}`,
              borderRadius: 20,
              padding: "26px 28px",
              display: "flex",
              alignItems: "flex-start",
              gap: 16,
              minHeight: 100,
              transition: "border-color 0.2s",
            }}
          >
            <div
              style={{
                fontFamily: BRAND.fonts.primary,
                fontSize: 26,
                color: COLORS.text,
                flex: 1,
                lineHeight: 1.4,
              }}
            >
              {visibleText}
              <span
                style={{
                  display: "inline-block",
                  width: 2,
                  height: 26,
                  backgroundColor: cursorBlink ? COLORS.text : "transparent",
                  marginLeft: 2,
                  verticalAlign: "middle",
                }}
              />
            </div>
            <div
              style={{
                width: 44,
                height: 44,
                borderRadius: 12,
                backgroundColor:
                  charsShown >= PROMPT.length ? COLORS.orange : "#2a2b2d",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                fontFamily: BRAND.fonts.marketing,
                color: charsShown >= PROMPT.length ? "#fff" : COLORS.textSubtle,
                fontSize: 22,
                fontWeight: 600,
                flexShrink: 0,
              }}
            >
              ↑
            </div>
          </div>
        </ClaudeChrome>
      </div>
    </AbsoluteFill>
  );
};

